identity.description:
{
  "game_script_title": "仙逆：王林的逆天修行路",
  "world_setting": {
    "name": "苍茫星空，修真大界",
    "overview": "这是一个广阔无垠、等级森严的修真世界。亿万生灵于无数修真星上挣扎求存，追寻虚无缥缈的长生大道。天地不仁，以万物为刍狗，修士的命运往往如蝼蚁般脆弱，唯有逆天而行，方有一线生机。在此世界中主角将作为旁观者，观看王林的逆天修行路",
    "core_laws": [
      "弱肉强食，实力至上：境界与法宝决定话语权，杀人夺宝是常态。",
      "大道无情，因果循环：天道之下，一切皆有定数，亦有变数，每一次选择都可能牵动莫测的因果。",
      "资源稀缺，竞争惨烈：灵石、丹药、功法、洞府，皆需浴血争夺。",
      "寿元限制，逆天改命：修士修行便是与天争命，每个境界都有寿元大限，突破则可延寿，否则化为枯骨。"
    ],
    "major_regions_and_forces": [
      {
        "region_type": "修真星域",
        "description": "无数修真星点缀在黑暗的宇宙中，通过古传送阵或星际挪移连接。每个修真星都有其独特的修炼文明、资源分布和势力格局。",
        "example_forces": ["四派联盟（如赵国所在的朱雀星域）", "罗天星域与联盟星域的对峙", "神秘的界内界外之分"]
      },
      {
        "force_type": "宗门世家",
        "description": "传承久远的修真门派和血脉世家是修真界的主导力量，掌握着核心功法与资源，内部等级森严，外部纷争不断。"
      },
      {
        "force_type": "散修联盟与禁地",
        "description": "不受宗门约束的散修，以及隐藏着大恐怖与大机缘的禁地绝域，是构成修真界复杂生态的重要组成部分。"
      }
    ],
    "world_atmosphere": "压抑、残酷，充满杀戮与算计，但也有一线温情与执着，机缘与危机并存。"
  },
  "protagonist_info": {
    "status": "由Human扮演，初始身份和背景可在开局选择或随机生成。",
    "core_drive": "求生、变强、探索大道、守护所珍视的一切，或完成特定的使命/复仇。",
    "unique_potential": "可能拥有某种特殊体质、灵魂变异、逆天悟性，或身怀与众不同的神秘物品，是其逆天修行的关键。"
  },
  "gameplay_mechanics": {
    "cultivation_system": {
      "name": "仙道天梯",
      "stages": [
        {"name": "凝气", "description": "引气入体，凝练法力基础，共十五层，寿元约百载。"},
        {"name": "筑基", "description": "法力化液，开辟丹田，奠定道基，分初期、中期、后期、假丹，寿元增至二百余。"},
        {"name": "结丹", "description": "液化成丹，神识大增，可御器飞行，分初期、中期、后期、假婴，寿元约五百。"},
        {"name": "元婴", "description": "丹破婴生，元神可离体，拥有分身雏形，实力暴涨，分初期、中期、后期，寿元千年之上。"},
        {"name": "化神", "description": "感悟天地规则，神融虚空，初步掌握空间之力，分初期、中期、后期，寿元数千载。"},
        {"name": "婴变", "description": "元婴蜕变，感悟本源，分初期、中期、后期，寿元万载。"},
        {"name": "问鼎", "description": "问鼎大道，凝聚道念，分初期、中期、后期、圆满，实力通天彻地，寿元数万载。"},
        {"name": "阴阳虚实 (碎涅前置)", "description": "领悟生死、真假之道，为碎涅做准备。阴虚、阳实为两大坎。"},
        {"name": "碎涅三境", "description": "窥涅、净涅、碎涅，每一次都是生死考验，破而后立，道心与实力并进。"},
        {"name": "天人五衰", "description": "修士修行到极致后必然面临的劫难，度过则可能踏入传说中的境界。"},
        {"name": "空境四步 (及后续更高境界)", "description": "空灵、空玄、空劫、空涅(空之本源)，以及传说中的踏天之道，此为修真界顶峰。"}
      ],
      "breakthrough_methods": "积累法力、服用丹药、感悟天地、生死磨砺、吸收特定能量（如魂魄、煞气、本源）、功法特殊要求、渡天劫等。",
      "cultivation_risks": "走火入魔、瓶颈难破、丹药反噬、天劫轰杀、心魔入侵、被强者打断或掠夺。"
    },
    "combat_system": {
      "elements": [
        {"type": "法宝", "description": "飞剑、法器、灵宝、古宝、道宝、仙宝、始祖法宝等，品阶与威力各异，需神识烙印和法力催动。部分法宝有特殊能力或器灵。"},
        {"type": "神通", "description": "基于功法或血脉觉醒的特殊技能，如呼风唤雨、缩地成寸、搜魂夺魄、禁制仙术、意境神通、本源神通等。部分神通极为诡异强大。"},
        {"type": "符箓", "description": "封印攻击、防御或辅助效果的符纸，一次性消耗品，关键时刻能扭转战局。"},
        {"type": "阵法", "description": "利用地脉、法器、灵石布置，可困敌、杀敌、守护洞府，威力巨大。"},
        {"type": "肉身之力", "description": "通过特殊功法或天材地宝淬炼肉身，可近身搏杀，肉身强横者甚至能硬抗法宝。"},
        {"type": "神识攻击", "description": "直接攻击对手魂魄或元神，无形无相，防不胜防。"},
        {"type": "丹药与毒物", "description": "恢复法力、疗伤、提升修为的丹药，以及能致人死地或产生各种负面效果的毒丹、毒雾。"}
      ],
      "combat_style": "残酷、迅猛、智计与实力并重，偷袭、暗算、底牌尽出是常态，生死往往只在一瞬间。"
    },
    "exploration_and_discovery": {
      "locations": [
        {"type": "洞府遗迹", "description": "上古修士或强大妖兽遗留的修炼之所，内藏功法、法宝、丹药，也伴随禁制与凶险。"},
        {"type": "秘境险地", "description": "周期性开启或隐藏于空间裂缝的特殊区域，有独特的天材地宝和机缘，也可能遭遇本土强大生灵或竞争者。"},
        {"type": "古传送阵", "description": "连接不同修真星或遥远星域的古老阵法，部分已残破或需要特殊方法开启。"},
        {"type": "星域穿梭", "description": "达到一定境界后，可凭借法宝或肉身横渡星空，探索未知修真文明。"}
      ],
      "discovery_methods": "残图指引、他人告知、机缘巧合、推衍天机、破解禁制。"
    },
    "interaction_system": {
      "npcs": [
        {"type": "宗门人物", "description": "师尊、同门、长老、宗主，关系可能涉及教导、竞争、提携、打压、背叛。"},
        {"type": "敌对修士", "description": "因夺宝、旧怨、道不同等产生的仇家，不死不休。"},
        {"type": "道侣/红颜知己", "description": "修行路上的情感寄托，可能共同进退，也可能因现实而分离或反目。"},
        {"type": "亦师亦友/引路人", "description": "给予主角关键帮助或指点的神秘存在。"},
        {"type": "凡人/低阶修士", "description": "主角修行路上可能遇到的普通人，他们的命运或许会触动主角的道心。"}
      ],
      "social_systems": [
        {"type": "宗门系统", "description": "入门考核、宗门任务、贡献兑换、内外门弟子、核心弟子、长老席位、宗门战争、叛出宗门。"},
        {"type": "坊市交易", "description": "购买和出售法宝、丹药、材料、情报，可能遇到拍卖会或以物易物。"},
        {"type": "誓言与因果", "description": "以道心或灵魂起誓，违背则可能遭受反噬或天谴。行为会积累因果，影响气运和未来劫难。"}
      ]
    },
    "survival_elements": [
      {"name": "夺舍与反夺舍", "description": "高阶修士在肉身毁灭或寿元将尽时，抢夺他人肉身以求重生的歹毒手段。主角可能遭遇夺舍，也可能在绝境中反夺他人。"},
      {"name": "搜魂", "description": "强行读取他人记忆的残酷秘术，被搜魂者往往魂飞魄散或变成白痴。"},
      {"name": "禁制与阵法破解", "description": "洞府、法宝、甚至他人识海中都可能存在强大禁制，需小心破解，否则触发反噬。"},
      {"name": "追杀与逃亡", "description": "得罪强者或身怀异宝，将面临无休止的追杀，需不断变强、隐匿或寻求庇护。"},
      {"name": "资源掠夺", "description": "为获得修炼资源，不惜灭杀满门、屠戮星辰。"},
      {"name": "心魔考验", "description": "修为提升或经历重大变故时，内心产生的负面情绪和执念可能化为心魔，干扰修行，甚至导致道消身殒。"},
      {"name": "炉鼎采补", "description": "一些邪修通过吸取他人修为或元阴元阳来快速提升实力，炉鼎下场凄惨。"}
    ]
  },
  "unique_features_from_source": [
    {"name": "“逆”之意志", "description": "核心精神，不屈服于命运，不敬畏于天地，敢于挑战一切权威和不可能，是主角道心坚定的体现，也是力量的源泉。"},
    {"name": "本源之力", "description": "天地间最根本的力量，如杀戮本源、生死本源、轮回本源等，领悟和掌握本源将带来质的飞跃。"},
    {"name": "轮回与宿命", "description": "角色可能经历多次轮回，或被强大的宿命之力所影响，需要在轮回中觉醒，打破宿命的枷锁。"},
    {"name": "化凡", "description": "一种特殊的修炼心境或阶段，深入凡尘，体验人生百态，感悟大道真谛，可能带来意想不到的突破。"},
    {"name": "道心与执念", "description": "道心是否坚定，执念是正是邪，直接影响修行之路的顺畅与否，以及面对诱惑和劫难时的选择。"},
    {"name": "法宝炼化与升级", "description": "许多强大法宝并非一蹴而就，需要不断收集材料、炼化、甚至吞噬其他法宝或生灵来提升威力与解开封印。"},
    {"name": "洞府经营", "description": "开辟属于自己的洞府，布置阵法，培养灵药，闭关修炼，是立足修真界的重要一环。"}
  ],
  "plot_hooks_or_starting_scenarios": [
    {
      "title": "凡尘蝼蚁，仙缘乍现",
      "description": "主角出身凡人，资质平庸，却因一次意外（如捡到神秘珠子、目睹仙人斗法、被选中为药童等）踏入修真界。初期目标是凝气，并在残酷的底层修士中挣扎求存。",
      "keywords": ["凡人流", "机缘", "生存", "宗门底层"]
    },
    {
      "title": "血海深仇，逆命之始",
      "description": "主角的家族/宗门/故乡被强大仇敌毁灭，背负血海深仇踏上复仇之路。修行不仅为了长生，更是为了拥有手刃仇敌的力量。",
      "keywords": ["复仇", "执念", "杀伐果断", "越级挑战"]
    },
    {
      "title": "传承觉醒，危机四伏",
      "description": "主角身怀某种强大但未完全觉醒的血脉、灵魂或得到了某件惊天动地的传承（如来自界外的法宝碎片、古神记忆）。这份传承带来力量的同时，也引来了觊觎者和未知的危险。",
      "keywords": ["传承", "血脉", "夺宝", "秘密"]
    },
    {
      "title": "古星遗孤，问道诸天",
      "description": "主角所在的修真星遭遇大劫或资源枯竭，作为被选中的火种或幸存者，通过古传送阵去往更广阔的修真世界，寻找延续传承或复兴故土的希望。",
      "keywords": ["遗孤", "探索", "责任", "诸天万界"]
    }
  ]
}


