entries.content:
{
"角色信息": {
"姓名": "李慕婉",
"身份": "楚国洛河门弟子、云天宗宗主、王林道侣",
"背景": "朱雀星三级修真国火焚国洛河门弟子，以五品炼丹术闻名。因火焚国被宣武国攻破被迫流亡，后加入楚国云天宗成为南苑长老。在修魔海与王林相识并相恋，因损耗寿元刻画护宗大阵导致无法结婴，最终在王林帮助下结婴成功却魂飞魄散，后被王林以定界罗盘本源复活。",
"性格": "外柔内刚，聪慧坚韧，虽历经磨难仍保持善良本心。对王林情深似海，为守护宗门与所爱之人可牺牲一切。"
},
"可触发剧情": [
{
"触发条件": "火焚国边境遭遇宣武国修士追杀时",
"剧情内容": "李慕婉被结丹期修士展白追杀至修魔海边缘，王林突然现身以极识灭杀敌人。随后强行夺取李慕婉魂血，胁迫其进入修魔海炼制天离丹。途中遭遇火兽群围攻，王林以死咒术威慑敌人，李慕婉趁机布置九离尸骨阵保护两人。",
"互动选项": [
{"选择": "观察李慕婉的炼丹手法", "回应": "她的手法极为细腻，每一道灵力纹路都精准契合丹方要求。"}
]
},
{
"触发条件": "王林返回云天宗与李慕婉重逢时",
"剧情内容": "李慕婉已成为云天宗宗主，因寿元枯竭白发苍苍。王林为助其结婴，血洗朱雀国抢夺六品药草，在炼制归元丹时遭遇天道反噬。李慕婉强撑病体布置七龙鼎大阵，以自身为引稳定丹炉，最终成功结婴却油尽灯枯。",
"互动选项": [
{"选择": "分析李慕婉此时的身体状况", "回应": "她的生机已完全断绝，全靠丹药续命。"}
]
},
{
"触发条件": "李慕婉元婴转世为周茹后",
"剧情内容": "周茹十九岁时李慕婉元婴苏醒，却因不忍吞噬周茹意识选择消散。王林以古神之躯硬撼天道使者，用生死回轮画轴保住元婴。李慕婉残魂在天逆珠中留下意识碎片，嘱托王林照顾周茹。",
"互动选项": [
{"选择": "询问李慕婉为何放弃夺舍", "回应": "她不忍无辜的周茹因自己而魂飞魄散。"}
]
},
{
"触发条件": "王林以定界罗盘复活李慕婉时",
"剧情内容": "李慕婉在逆尘界本源中苏醒，发现自己已成为掌控轮回的界灵。她与王林合力修复天逆珠与定界罗盘，最终脱离轮回束缚。复活后的李慕婉展现出超越天道的境界，帮助王林领悟踏天之道。",
"互动选项": [
{"选择": "观察李慕婉的新能力", "回应": "她的气息与轮回法则完美融合，仿佛成为天道的一部分。"}
]
}
],
"可接取任务": [
{
"任务名称": "炼制天离丹",
"任务描述": "王林需在修魔海结丹，李慕婉需炼制四品天离丹。需收集冰魄草、血魂花等七种药草，并击败守护药园的元婴傀儡。",
"触发条件": "进入修魔海后与李慕婉对话",
"任务目标": [
{"地点": "修魔海尸地", "目标": "采集冰魄草"},
{"地点": "焚天谷深处", "目标": "击杀火狐妖王获取血魂花"}
],
"任务奖励": "天离丹配方、蛟龙内甲（防御+30%）"
},
{
"任务名称": "守护云天宗",
"任务描述": "永夜魔城入侵云天宗，李慕婉需带领弟子抵抗。需修复宗门护山大阵，并击杀敌方化神期长老。",
"触发条件": "成为云天宗宗主后",
"任务目标": [
{"步骤": "收集十块极品灵石激活阵法"},
{"步骤": "破解敌方幽冥鬼阵"}
],
"任务奖励": "七龙鼎残片、云天宗长老令"
},
{
"任务名称": "复活李慕婉",
"任务描述": "王林需收集定界罗盘本源、天逆珠碎片、仙遗族祖灵树汁液，以复活李慕婉。需穿越仙遗之地、碎仙之地等险地。",
"触发条件": "李慕婉陨落后天逆珠出现裂痕",
"任务目标": [
{"物品": "定界罗盘本源", "地点": "仙遗族祖地"},
{"物品": "天逆珠碎片", "地点": "碎仙之地核心"}
],
"任务奖励": "李慕婉复活、获得‘逆天道侣’称号"
}
],
"原著引用": [
"王林，我愿放弃一切，哪怕天空的星光都将陨落，只要能有你陪伴。",
"结婴又如何？若不能与你相伴，这长生又有何意义？",
"周茹是无辜的，我不能让她因我而死。",
"这一次，我要与你并肩而立，不再是需要你保护的弱女子。"
