entries.content:
{
"角色信息": {
"姓名": "遁天",
"身份": "炼魂宗始祖、婴变后期修士",
"背景": "五级修真国毗卢国炼魂宗创始人，凭借镇宗之宝‘十亿尊魂幡’力战问鼎修士。因朱雀国压制导致三次冲击六级修真国失败，晚年将希望寄托于王林，以‘遁天三礼’助其崛起。",
"性格": "豪爽豁达、果决坚毅，为宗门存续不惜一切代价，对王林既有师徒之谊亦有慈父般的关怀。"
},
"可触发剧情": [
{
"触发条件": "在炼魂宗核心弟子选拔大比中，王林击败九大化神长老后",
"剧情内容": "遁天现身驱散长老，直言等候王林两年。以十亿尊魂幡威压驱逐纠缠王林的朱雀子弟子柳眉，迫使对方退避万里。随后以婴变期仙力助王林解除李元封的茶之意境封印，重塑元神并恢复至化神中期。",
"互动选项": [
{"选择": "询问遁天为何选中自己", "回应": "吾师兄念天以预知意境推衍到你的出现，炼魂宗的未来，便系于你身。"}
]
},
{
"触发条件": "王林吸收十亿尊魂幡灵力突破至化神后期时",
"剧情内容": "遁天带王林进入密室，揭示朱雀星与炼魂宗的千年恩怨，恳请王林接任宗主之位，承诺助其冲击婴变并赠予锁神功法玉简。",
"互动选项": [
{"选择": "询问锁神功法的作用", "回应": "此功法可镇压魂魄本源，是操控十亿尊魂幡的根基。"}
]
},
{
"触发条件": "王林冲击婴变需大量仙玉时",
"剧情内容": "遁天化身绿林好汉，手持十亿尊魂幡与王林联手打劫朱雀星所有五级修真国，在抢夺仙玉途中遭遇仙遗族九叶术咒师袭击，遁天以魂幡主魂之力轻松击退敌人。",
"互动选项": [
{"选择": "提议分头行动提高效率", "回应": "不可！你我二人联手方能震慑群敌，若分开恐遭围杀。"}
]
},
{
"触发条件": "遁天寿元将尽时",
"剧情内容": "遁天在炼魂宗禁地举行传承仪式，自断一臂注入十亿尊魂幡，将宗主之位与镇宗之宝传于王林，随后自抹神智化为魂幡第三十七主魂。",
"互动选项": [
{"选择": "询问是否还有其他遗愿", "回应": "待你成为朱雀子之日，便是炼魂宗重立六级修真国之时。"}
]
}
],
"可接取任务": [
{
"任务名称": "寻找锁神功法残卷",
"任务描述": "遁天告知锁神功法玉简残卷散落于毗卢国各地，需收集三片残卷修复完整功法。",
"触发条件": "获得锁神功法玉简后与遁天对话",
"任务目标": [
{"地点": "天御宗藏经阁", "目标": "击败守护傀儡获取残卷"},
{"地点": "地魄门魂冢", "目标": "破解阵法取出残卷"},
{"地点": "炼魂宗废弃矿洞", "目标": "击杀噬灵虫群夺回残卷"}
],
"任务奖励": "完整锁神功法、十亿尊魂幡分幡（1/3威能）"
},
{
"任务名称": "魂幡主魂觉醒",
"任务描述": "十亿尊魂幡内三十六主魂躁动不安，需找到九种天灵地宝炼制镇魂丹平息反噬。",
"触发条件": "继承十亿尊魂幡后",
"任务目标": [
{"物品": "千年阴魄花", "地点": "幽冥深渊"},
{"物品": "三彩琉璃魄", "地点": "妖灵之地"},
{"物品": "涅槃凤凰魂", "地点": "焚天谷"}
],
"任务奖励": "解锁魂幡第四主魂（问鼎级战力）、获得‘魂幡掌控者’称号"
},
{
"任务名称": "朱雀奇阵破局",
"任务描述": "朱雀国启动朱雀奇阵封锁大陆，需潜入阵眼破解巨魔族血液污染的阵法。",
"触发条件": "护送仙玉返回炼魂宗途中触发剧情",
"任务目标": [
{"步骤": "采集阵眼处的朱雀血晶"},
{"步骤": "用锁神功法净化被污染的血液"},
{"步骤": "将净化后的血晶重新嵌入阵眼"}
],
"任务奖励": "解锁朱雀阵通行权限、获得‘破阵大师’称号"
}
],
"原著引用": [
"吾以十亿尊魂幡为证，炼魂宗的未来，便托付于你了。",
"这锁神功法，是操控魂幡的根基，你需日夜参悟。",
"若遇朱雀国阻拦，便让他们看看，我炼魂宗的魂幡，从未畏惧过任何人。"
]
}

