entries.content:
{
  "game_world_geography": {
    "world_name": "仙逆苍茫宇宙",
    "overview": "这是一个由无数界域、星域与修真星构成的多层次宇宙。从凡人居住的星球，到修士纵横的修真星，再到广袤无垠的星域，乃至神秘莫测的界内界外，每一个角落都充满了未知、机缘与致命的凶险。空间壁垒与古传送阵是连接不同区域的主要途径，而强大的修士更能凭借肉身或法宝横渡星空。",
    "cosmic_structure": {
      "name": "洞府界与界外苍茫",
      "description": "整个《仙逆》宇宙的核心认知围绕着“洞府界”及其之外的广阔天地展开。洞府界本身被一层巨大的封印所笼罩，是此界生灵认知中的“家园”。界外则是更为原始、更为残酷、也更为广阔的苍茫星空，蕴藏着无数秘密和更强大的存在。",
      "elements": [
        {
          "name": "洞府界 (Sealed Realm)",
          "details": "可以理解为被某种大神通封印起来的一个庞大宇宙空间，包含多个星域。此界的天地规则相对完整，但受到封印的影响，其上限受到压制。是主角早期成长和故事展开的主要舞台。"
        },
        {
          "name": "界内 (Inner Realm)",
          "details": "通常指洞府界内，由“联盟星域”与“罗天星域”两大势力范围构成。这两大星域之间常年征战，关系紧张。界内的修真文明发展相对成熟，宗门林立，传承有序。"
        },
        {
          "name": "界外 (Outer Realm)",
          "details": "指洞府界封印之外的无垠星空。界外的规则更为混乱和原始，充满了未知的危险与机遇。这里的修真文明形态各异，强者如云，生存环境比界内残酷百倍。著名的界外星域有云海星域、召河星域、七彩仙尊界等。"
        },
        {
          "name": "苍茫星空 (Boundless Starry Sky)",
          "details": "一个更为宏观的宇宙概念，可能包含了无数个类似洞府界的存在，以及传说中的古国、神话时代的遗迹。这是更高层次探索的区域，涉及宇宙的本源和更古老的秘密。"
        }
      ]
    },
    "major_star_domains": [
      {
        "name": "朱雀星域 (Vermilion Bird Star Domain)",
        "location_tier": "洞府界 - 联盟星域南部边缘",
        "description": "以修真星朱雀星为核心的星域，是主角最初踏足修真界并崛起的重要地点。此地修真水平在联盟星域中相对较低，但也是一切传奇的开端。",
        "key_locations": [
          "朱雀星 (Planet Vermilion Bird): 四级修真星，恒岳派、玄道宗等宗门所在地，拥有朱雀圣宗的传承。",
          "雨之仙界 (Rain Celestial Realm): 一处特殊的残破仙界，周期性开启，内藏仙人传承与危机。",
          "血色禁地 (Blood-Red Forbidden Land): 充满杀戮与煞气的试炼之地。"
        ],
        "characteristics": "早期竞争激烈，资源相对贫乏。修真者以凝气、筑基、结丹、元婴为主。朱雀圣魂是此地独特的力量象征。"
      },
      {
        "name": "联盟星域 (Alliance Star Territory)",
        "location_tier": "洞府界 - 界内",
        "description": "由众多修真星域组成的庞大联盟，与罗天星域对峙。其核心区域修真文明发达，强者众多，拥有修真联盟总部。",
        "key_locations": [
          "昆虚星域 (Kunxu Star Domain): 修真联盟总部所在地，高手云集，是联盟的政治、经济、军事中心。",
          "天运星 (Planet Heaven's Luck): 曾是六级修真国天运国所在，司徒南的故乡，后衰落。",
          "弃星 (Abandoned Star): 因某种原因被废弃的修真星，常有流放者或特殊机遇。"
        ],
        "characteristics": "宗门势力错综复杂，竞争激烈，时有摩擦。化神、婴变、问鼎修士是中坚力量。古传送阵是连接各星域的重要枢纽。"
      },
      {
        "name": "罗天星域 (Luotian Star Territory)",
        "location_tier": "洞府界 - 界内",
        "description": "与联盟星域并立的另一大势力范围，同样广阔，内部亦有诸多家族和宗门。整体风格可能更为尚武或有其独特的修炼体系。",
        "key_locations": [
          "罗天主星 (Luotian Prime Star): 罗天星域的核心，戒备森严，强者如林。",
          "雷之仙界 (Thunder Celestial Realm): 另一处残破仙界，与雷霆本源相关，充满凶险。"
        ],
        "characteristics": "修士同样强大，可能拥有与联盟星域不同的特色神通或法宝。与联盟星域常年处于战争或冷战状态。"
      },
      {
        "name": "云海星域 (Cloud Sea Star Domain)",
        "location_tier": "界外",
        "description": "界外著名的庞大星域，由无数星辰与星云构成，如同一片无边无际的云之海洋。这里的修士更为强大，规则也更为残酷。",
        "key_locations": [
          "第一花（指界外某个重要区域，具体名称可能因剧情推进而变化）",
          "众多被称为“雾兽”的本土强大生灵栖息地。"
        ],
        "characteristics": "界外法则显露更为直接，强者生存，弱者淘汰。碎涅三境的修士在这里也只是中上游。星空风暴和空间裂缝是常见危险。"
      },
      {
        "name": "召河星域 (Zhaohe Star Domain)",
        "location_tier": "界外",
        "description": "另一个广阔的界外星域，可能拥有不同于云海星域的独特文明和势力格局。",
        "key_locations": [
          "（具体地点依原著后续展开）"
        ],
        "characteristics": "同样是界外强者的舞台，可能存在独特的本源力量或古老传承。"
      },
      {
        "name": "七彩仙尊界 (Seven-Colored Immortal Sovereign Realm)",
        "location_tier": "界外（或特殊空间）",
        "description": "与七彩仙尊相关的特殊界域，可能是一个洞府世界，也可能是一片独立的星空。红蝶等角色与此地有莫大关联。",
        "key_locations": [
          "七彩道人传承之地。"
        ],
        "characteristics": "充满了七彩仙尊留下的禁制、考验和传承，是一个充满机遇与凶险的密地。"
      }
    ],
    "special_dimensions_and_planes": [
      {
        "name": "古神之地 (Land of the Ancient Gods)",
        "description": "上古时期古神一族居住或陨落之地，充满了古神之力和他们的传承。对于修炼古神诀的修士而言，是至关重要的试炼与提升场所。",
        "access_methods": "通常需要特殊的信物、血脉感应或通过特定的空间裂缝才能进入。",
        "dangers_and_opportunities": "古神禁制、强大的古神傀儡、其他觊觎传承的修士。机遇包括古神记忆、古神法宝、星点以及肉身力量的极致提升。"
      },
      {
        "name": "仙界碎片 (Celestial Realm Fragments)",
        "description": "上古仙界破碎后散落的残块，如雨之仙界、雷之仙界等。这些碎片中可能还保留着部分仙界的环境、仙气以及仙人的传承或遗宝。",
        "characteristics": "规则不完整，空间不稳定，但往往蕴含着超越凡间修真界的力量和物品。是修士们趋之若鹜的探险之地。"
      },
      {
        "name": "各个大能修士的洞府世界 (Cave Worlds of Powerful Cultivators)",
        "description": "修为达到一定境界的强大修士，可以开辟出属于自己的小型洞府世界，用于修炼、储物或传承。这些洞府世界大小不一，内部规则由开辟者制定。",
        "examples": "仙帝洞府、特定强者的传承空间等。"
      },
      {
        "name": "轮回之地/冥界（概念）",
        "description": "涉及生死轮回的神秘空间，凡人死后魂魄归处，也可能与某些特殊功法（如轮回本源）或种族相关。具体形态和规则极为隐秘。",
        "accessibility": "极难到达，通常只有掌握特殊神通或处于特定状态（如濒死、魂游）才可能触及。"
      }
    ],
    "means_of_travel": [
      "古传送阵 (Ancient Teleportation Arrays): 连接不同修真星或遥远星域的主要方式，部分已残破或需要特殊方法激活。",
      "星梭/星舟 (Star Shuttles/Boats): 特殊炼制的飞行法宝，用于在星域内或短距离星际航行。",
      "肉身横渡 (Physical Traversal): 高阶修士凭借强大肉身和修为，可以直接在星空中飞行，但速度和距离受修为限制，且消耗巨大。",
      "挪移/撕裂空间 (Spatial Shift/Tearing Space): 掌握空间法则的大能修士，可以进行短距离的空间跳跃或撕裂空间壁垒进行穿梭，但风险极高。",
      "界域通道 (Realm Passages): 连接不同大界域的稳定或不稳定通道，极为罕见，常有重兵把守或强大禁制。"
    ]
  }
}

