{
  "title": "仙逆世界观：阵法与禁制概述",
  "version": "1.0",
  "description": "概述了《仙逆》小说中阵法与禁制的基本概念、分类、特点以及与主角相关的认知。",
  "core_concepts": {
    "阵法": {
      "definition": "阵法乃是借助特定方位、器物、符文乃至天地之力，构建出具有特定攻、防、困、幻、辅助等效果的场域。其布置精巧，变化多端，威力大小与布阵者修为、阵法材料、以及对天地规则的感悟息息相关。",
      "types": [
        {
          "name": "攻击类阵法",
          "description": "以杀伤、破坏为主要目的，如剑阵、雷阵等，能够汇聚能量对敌人造成毁灭性打击。"
        },
        {
          "name": "防御类阵法",
          "description": "以守护、抵挡为主要目的，如护山大阵、守护光罩等，能够形成坚固屏障，抵御外来攻击。"
        },
        {
          "name": "困缚类阵法",
          "description": "以限制、束缚敌人行动为目的，如迷踪阵、锁灵阵等，使敌人陷入其中难以脱身。"
        },
        {
          "name": "幻术类阵法",
          "description": "以制造幻象、迷惑心神为主要目的，能令敌人陷入虚假景象，不辨真伪。"
        },
        {
          "name": "辅助类阵法",
          "description": "提供各种增益效果，如聚灵阵（汇聚天地灵气辅助修炼）、传送阵（实现远距离空间跳跃）等。"
        },
        {
          "name": "复合型阵法",
          "description": "兼具多种阵法效果，布置更为复杂，威力也更为强大，通常是高级阵法的体现。"
        }
      ],
      "protagonist_interaction": "主角在历练过程中，不仅学习和掌握了多种基础及高级阵法，更凭借其过人的悟性与机缘，时常能看破他人阵法的玄奥，甚至进行改良与创新。阵法是主角克敌制胜、探索秘境的重要手段之一。"
    },
    "禁制": {
      "definition": "禁制是一种更为微观和精妙的能量运用法门，常通过特殊手法将能量、神识或法则之力凝聚、铭刻于物品、地域或生灵体内，形成特定的约束、封印或触发效果。禁制往往隐匿难寻，破解需要极高的技巧和眼力。",
      "types": [
        {
          "name": "封印类禁制",
          "description": "用于封锁力量、记忆、通道或特定区域，如封印妖兽、尘封古宝等。"
        },
        {
          "name": "守护类禁制",
          "description": "附加于宝物或重要地点，防止外人轻易获取或侵入，一旦触动可能引发反击。"
        },
        {
          "name": "触发类禁制",
          "description": "在满足特定条件时自动激活，产生预设效果，常用于陷阱、传承或警示。"
        },
        {
          "name": "追踪类禁制",
          "description": "附着于目标身上，使其难以摆脱，便于施术者定位。"
        },
        {
          "name": "操控类禁制",
          "description": "用于控制他人心神或行动，是一种极为阴险歹毒的禁制手段。"
        }
      ],
      "protagonist_interaction": "主角对于禁制的理解和运用同样达到了极高境界。他不仅能够破解许多上古禁制，获取机缘，还擅长在敌人或物品上施加自己的独特禁制，用于追踪、控制或作为后手。主角对禁制的敏感度和破解能力，多次助其化险为夷。"
    },
    "common_elements": {
      "learning_and_mastery": "阵法与禁制的学习需要深厚的修为基础、强大的神识、以及对天地法则的深刻感悟。通常需要传承、图谱或名师指点，天赋与毅力缺一不可。主角常通过实战、感悟以及夺取他人心得来提升自己的阵法禁制造诣。",
      "materials_and_cost": "布置强大的阵法或施展高级禁制，往往需要珍稀的材料（如灵石、特殊矿物、妖丹等）作为能量源或阵基，消耗巨大。",
      "breaking_methods": "破解阵法与禁制通常有强力破除（以绝对力量摧毁）、技巧破解（找到阵眼或禁制核心，以巧破之）、以及利用相克原理等方式。主角往往擅长通过神识推衍，寻找其薄弱环节。"
    }
  }
}

